import sys

def evaluate_postfix(expression):
    tokens = expression.split()
    if not tokens:
        return 0
    stack = []
    ops = {'+', '-', '*', '/'}
    for token in tokens:
        if token in ops:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # '/'
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[-1]

if __name__ == '__main__':
    data = sys.stdin.read().strip()
    print(evaluate_postfix(data))
